    for bit in bin(n)[2:]:
        c = a * (2 * b - a) % M  # F(2k)
        d = (a * a + b * b) % M  # F(2k+1)
        if bit == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a


def main():
