    out = []
    app = out.append
    for tok in sys.stdin.read().split():
        r = cache.get(tok)
        if r is None:
            r = str(fib(int(tok)))
            cache[tok] = r
        app(r)
    if out:
        sys.stdout.write("\n".join(out) + "\n")


